```go
package main

import "fmt"

func ordered(a, b int) (low, high int) {
    low, high = a, b
    if low > high { low, high = high, low }
    return low, high
}

func main() {
    fmt.Println(ordered(9, 2))
}
```
The output is `2 9`. The names explain each integer's role inside the declaration and body, while the caller still receives positional results.

```go
package main

import (
    "errors"
    "fmt"
)

func load(found bool) (value string, err error) {
    defer func() { fmt.Println("failed:", err != nil) }()
    if !found { return "", errors.New("not found") }
    return "ready", nil
}

func main() {
    value, err := load(false)
    fmt.Println(value, err)
}
```
The defer sees the error after the return expression assigns it. The program prints `failed: true` before the caller prints the empty value and `not found`.

```go
package main

import (
    "errors"
    "fmt"
)

func label(id int) (text string, err error) {
    if id <= 0 { return "", errors.New("id must be positive") }
    text = fmt.Sprintf("item-%d", id)
    return text, nil
}

func main() {
    fmt.Println(label(3))
}
```
The output is `item-3 <nil>`. Results are named for documentation, while both return sites still show the values they send.

```go
package main

import "fmt"

func named(n int) (text string, err error) {
    return fmt.Sprint(n), nil
}

func unnamed(n int) (string, error) {
    return fmt.Sprint(n), nil
}

func main() {
    var format func(int) (string, error)
    format = named
    fmt.Println(format(7))
    format = unnamed
    fmt.Println(format(8))
}
```
The output is `7 <nil>` and `8 <nil>`. Both declarations satisfy the same external function type.

```go
package main

import "fmt"

func choose(useInner bool) (value string) {
    value = "outer"
    if useInner {
        value := "inner"
        fmt.Println("inside:", value)
    }
    return value
}

func main() {
    fmt.Println("returned:", choose(true))
}
```
The output is `inside: inner` followed by `returned: outer`. Replacing `:=` with `=` updates the named result instead of creating a shadow.
